### Pattern 4: Asynchronous Event-Driven (Pub-Sub)

**Use Case**: Broadcasting state changes to multiple independent consumers requiring loose coupling.

**Architecture**:

```mermaid
graph TD
    Publisher[Eligibility Service] -->|Publish Event| Topic[MemberEligibilityChanged<br/>Event Topic]
    Topic -->|Subscribe| Sub1[Claims Service]
    Topic -->|Subscribe| Sub2[Member Portal]
    Topic -->|Subscribe| Sub3[ID Card Service]
    Topic -->|Subscribe| Sub4[Provider Directory]
    Topic -->|Subscribe| Sub5[Care Management]

    style Publisher fill:#90EE90
    style Topic fill:#FFD700
    style Sub1 fill:#87CEEB
    style Sub2 fill:#87CEEB
    style Sub3 fill:#87CEEB
    style Sub4 fill:#87CEEB
    style Sub5 fill:#87CEEB
```

**Implementation - Azure Service Bus Topic/Subscription**:

```csharp
// Event model
public class MemberEligibilityChangedEvent
{
    public string EventId { get; set; }
    public DateTime EventTimestamp { get; set; }
    public string MemberId { get; set; }
    public string OldPlanId { get; set; }
    public string NewPlanId { get; set; }
    public DateTime EffectiveDate { get; set; }
    public string ChangeReason { get; set; }
}

// Event publisher (Eligibility Service)
public class EligibilityService
{
    private readonly ServiceBusSender _topicSender;
    private readonly ILogger<EligibilityService> _logger;

    public async Task UpdateMemberEligibilityAsync(string memberId, string newPlanId, DateTime effectiveDate)
    {
        // Update eligibility in database
        var oldPlanId = await _repository.GetCurrentPlanAsync(memberId);
        await _repository.UpdatePlanAsync(memberId, newPlanId, effectiveDate);

        // Publish event to topic - all subscribers will receive
        var evt = new MemberEligibilityChangedEvent
        {
            EventId = Guid.NewGuid().ToString(),
            EventTimestamp = DateTime.UtcNow,
            MemberId = memberId,
            OldPlanId = oldPlanId,
            NewPlanId = newPlanId,
            EffectiveDate = effectiveDate,
            ChangeReason = "State Agency Update"
        };

        var message = new ServiceBusMessage(JsonSerializer.Serialize(evt))
        {
            MessageId = evt.EventId,
            Subject = "MemberEligibilityChanged",
            ContentType = "application/json"
        };

        await _topicSender.SendMessageAsync(message);

        _logger.LogInformation(
            "Published MemberEligibilityChanged event for member {MemberId}: {OldPlan} -> {NewPlan}",
            memberId, oldPlanId, newPlanId);
    }
}

// Event subscriber - Claims Service
public class ClaimsServiceEventHandler : BackgroundService
{
    private readonly ServiceBusProcessor _processor;
    private readonly IClaimsConfigurationService _claimsConfig;
    private readonly ILogger<ClaimsServiceEventHandler> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _processor.ProcessMessageAsync += HandleEligibilityChangedAsync;
        _processor.ProcessErrorAsync += ErrorHandler;

        await _processor.StartProcessingAsync(stoppingToken);
        await Task.Delay(Timeout.Infinite, stoppingToken);
    }

    private async Task HandleEligibilityChangedAsync(ProcessMessageEventArgs args)
    {
        var evt = JsonSerializer.Deserialize<MemberEligibilityChangedEvent>(
            args.Message.Body.ToString());

        try
        {
            _logger.LogInformation(
                "Received MemberEligibilityChanged event for member {MemberId}",
                evt.MemberId);

            // Update claims adjudication rules for new plan
            await _claimsConfig.UpdateAdjudicationRulesAsync(evt.MemberId, evt.NewPlanId);

            await args.CompleteMessageAsync(args.Message);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error handling eligibility change for member {MemberId}", evt.MemberId);
            await args.AbandonMessageAsync(args.Message);
        }
    }
}

// Event subscriber - ID Card Service
public class IdCardServiceEventHandler : BackgroundService
{
    private readonly ServiceBusProcessor _processor;
    private readonly IIdCardGenerationService _idCardService;
    private readonly ILogger<IdCardServiceEventHandler> _logger;

    private async Task HandleEligibilityChangedAsync(ProcessMessageEventArgs args)
    {
        var evt = JsonSerializer.Deserialize<MemberEligibilityChangedEvent>(
            args.Message.Body.ToString());

        try
        {
            _logger.LogInformation(
                "Generating new ID card for member {MemberId}",
                evt.MemberId);

            // Generate new ID card PDF asynchronously
            await _idCardService.GenerateIdCardAsync(evt.MemberId, evt.NewPlanId);

            await args.CompleteMessageAsync(args.Message);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error generating ID card for member {MemberId}", evt.MemberId);
            // Failure in ID card generation doesn't affect other subscribers
            await args.DeadLetterMessageAsync(args.Message, "GenerationFailed", ex.Message);
        }
    }
}

// Configuration - Topic and Subscriptions
builder.Services.AddSingleton(sp =>
{
    var client = sp.GetRequiredService<ServiceBusClient>();
    return client.CreateSender("member-events-topic");
});

// Claims Service subscription with filter
builder.Services.AddSingleton(sp =>
{
    var client = sp.GetRequiredService<ServiceBusClient>();
    return client.CreateProcessor("member-events-topic", "claims-service-subscription");
});

// ID Card Service subscription with filter
builder.Services.AddSingleton(sp =>
{
    var client = sp.GetRequiredService<ServiceBusClient>();
    return client.CreateProcessor("member-events-topic", "idcard-service-subscription");
});
```

**Key Characteristics**:
- ✅ **Loose Coupling**: Publisher unaware of subscribers, can add/remove subscribers independently
- ✅ **Parallel Processing**: All subscribers receive event simultaneously
- ✅ **Service Autonomy**: Each subscriber processes event independently
- ✅ **Scalability**: Easy to add new subscribers without modifying publisher
- ✅ **Fault Isolation**: Subscriber failure doesn't affect publisher or other subscribers
- ❌ **Eventual Consistency**: Subscribers process event after delay
- ❌ **Debugging Complexity**: Difficult to trace event flow across subscribers
- ❌ **Message Ordering**: Events may be processed out of order by different subscribers

**When to Use**:
- Member eligibility changes affecting multiple systems
- Provider credentialing completion triggering multiple actions
- Claim adjudication completion for payment, notification, analytics
- Reference data updates (fee schedules, formularies) requiring cache invalidation

