```csharp
public class ClaimsConsumer : BackgroundService
{
    private readonly ServiceBusProcessor _processor;
    private readonly IClaimsAdjudicationService _adjudication;
    private readonly ILogger<ClaimsConsumer> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _processor.ProcessMessageAsync += ProcessMessageAsync;
        _processor.ProcessErrorAsync += ProcessErrorAsync;

        await _processor.StartProcessingAsync(stoppingToken);
        await Task.Delay(Timeout.Infinite, stoppingToken);
    }

    private async Task ProcessMessageAsync(ProcessMessageEventArgs args)
    {
        try
        {
            var claim = JsonSerializer.Deserialize<ClaimSubmission>(
                args.Message.Body.ToString());

            await _adjudication.AdjudicateAsync(claim);
            await args.CompleteMessageAsync(args.Message);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing message");
            await args.AbandonMessageAsync(args.Message);
        }
    }

    private Task ProcessErrorAsync(ProcessErrorEventArgs args)
    {
        _logger.LogError(args.Exception, "Message processor error");
        return Task.CompletedTask;
    }
}

// Register in Program.cs
builder.Services.AddHostedService<ClaimsConsumer>();
